update events set lead='Roma Street Parkland''s after-dark light trail returns with a new story, Night Flight: seven glowing zones to wander through, with food trucks and a bar on the lawn.', about='The Enchanted Garden returns to Roma Street Parkland from 20 November to 19 December 2026 with a new theme, Night Flight. Two young aviators, Ivy and Bert, guide visitors through a hidden world where light moves like wings, across seven immersive zones inspired by night-sky creatures and the parkland after dark.

Sessions start every 15 minutes from 6.30pm, with the last entry at 9.15pm. Tickets are $9.50 for anyone 13 and over, $7.50 for children aged 3 to 12, and free for children 2 and under. Buying tickets online through Oztix beforehand is essential.

Food trucks set up on Celebration Lawn from 5pm each day, alongside a licensed bar, and low-sensory sessions are available. The Enchanted Garden is a Queensland Government initiative delivered by City Parklands.', story='[{"type": "text", "text": "As the sun goes down over Roma Street Parkland, the gardens change character. Paths that are familiar by day glow with colour, and the Enchanted Garden opens for another season of walking through light.\n\nThis year''s story is Night Flight. Two aspiring aviators, Ivy and Bert, lead the way through a hidden world where light moves like wings, across seven zones inspired by the creatures of the night sky and the parkland after dark."}, {"type": "image", "url": "/images/library/unsplash-cmophoto-carousel.jpg", "alt": "Lit carousel at night decorated for Christmas", "layout": "right", "caption": "Stand-in photo: cmophoto.net. The Enchanted Garden photos coming soon"}, {"type": "text", "text": "Sessions start every 15 minutes from 6.30pm, so you can choose a time that suits little ones or make it a later outing after dinner. The last session goes in at 9.15pm.\n\nTickets are kept deliberately affordable: $9.50 for anyone 13 and over, $7.50 for children 3 to 12, and free for children 2 and under. Group tickets are also available. Tickets must be bought online through Oztix before you go.", "heading": "Sessions and tickets"}, {"type": "text", "text": "Arrive early and make an evening of it. Food trucks open on Celebration Lawn from 5pm every day, with a licensed bar for the grown-ups. Low-sensory sessions are available for visitors who prefer a calmer experience.", "heading": "Make a night of it"}]'::jsonb, highlights='[{"title": "7 zones", "detail": "Night Flight, new for 2026"}, {"title": "From $7.50", "detail": "Under 3s free"}, {"title": "Every 15 min", "detail": "6.30pm to 9.15pm nightly"}]'::jsonb, good_to_know='["Buy tickets online through Oztix before you go", "Sessions every 15 minutes, 6.30pm to 9.15pm", "Food trucks and a licensed bar on Celebration Lawn from 5pm", "Low-sensory sessions available", "Accessible event, with parking and public transport nearby", "Group tickets available"]'::jsonb, venue_about='Roma Street Parkland is a 16-hectare inner-city garden in Brisbane, a short walk from Roma Street station.', facebook_url='https://www.facebook.com/enchantedgardenbrisbane', instagram_url='https://www.instagram.com/enchantedgardenbrisbane', maps_url='https://www.google.com/maps/search/?api=1&query=Roma%20Street%20Parkland%2C%201%20Parkland%20Boulevard%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='enchanted-garden-night-flight';
update events set time_text='Friday 27 November, 6.30pm–7.30pm', lead='The moment Christmas officially begins in Brisbane: the Lord Mayor switches on the city''s 22-metre tree in King George Square, with Santa and live music from Jem Cassar-Daley.', about='Christmas in Brisbane officially begins on Friday 27 November, when Lord Mayor Adrian Schrinner lights the city''s 22-metre Christmas tree in King George Square for the first time this season.

The free evening runs from 6.30pm to 7.30pm, with live music from Australian singer-songwriter Jem Cassar-Daley and a visit from Santa and his helpers. No bookings are needed, and it suits all ages.

The tree, one of the largest in the Southern Hemisphere, continues a city tradition dating back to the 1950s and stays lit in King George Square until early January.', story='[{"type": "text", "text": "Every year, one evening in late November marks the start of Christmas in the city. On Friday 27 November, families, office workers and Christmas lovers gather in King George Square as Lord Mayor Adrian Schrinner switches on Brisbane''s Christmas tree for the first time.\n\nAt 22 metres tall, it''s one of the largest Christmas trees in the Southern Hemisphere, and it carries on a tradition that dates back to the 1950s."}, {"type": "image", "url": "/images/library/unsplash-abishanth-ahilan-fireworks.jpg", "alt": "Golden fireworks against a dark night sky", "layout": "right", "caption": "Stand-in photo: Abishanth Ahilan. Lord Mayor''s Lighting of the Christmas Tree photos coming soon"}, {"type": "text", "text": "The free celebration runs from 6.30pm to 7.30pm. Australian singer-songwriter Jem Cassar-Daley performs live, and Santa and his helpers make an appearance, so bring the children for a first glimpse of the big man this season.", "heading": "Music and a visit from Santa"}, {"type": "text", "text": "Make a night of it in the city. The City After Dark Markets fill Reddacliff Place on George Street from 4pm the same evening, with more than 70 food, artisan and boutique traders, a pop-up bar and live music. After the lighting, the tree stays lit in King George Square until early January, and from 4 December the City Hall Lights projections start next door.", "heading": "Before and after"}]'::jsonb, highlights='[{"title": "22-metre tree", "detail": "One of the largest in the Southern Hemisphere"}, {"title": "Free", "detail": "No bookings needed"}, {"title": "Since the 1950s", "detail": "A Brisbane Christmas tradition"}]'::jsonb, good_to_know='["Free, no bookings needed", "Runs 6.30pm to 7.30pm", "Suitable for all ages", "Arrive early for a good spot in the square", "City After Dark Markets are on in Reddacliff Place from 4pm", "The tree stays lit until early January"]'::jsonb, address='King George Square, 100 Adelaide Street, Brisbane City', venue_about='King George Square is Brisbane''s civic square, in front of City Hall, and home to the city''s Christmas tree each December.', maps_url='https://www.google.com/maps/search/?api=1&query=King%20George%20Square%2C%20100%20Adelaide%20Street%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='lord-mayors-lighting-of-the-christmas-tree';
update events set time_text='Friday 27 November, 4pm–9pm', lead='More than 70 food, artisan and boutique traders take over Reddacliff Place on Black Friday night, with a pop-up bar, live music and themed lighting.', about='Brisbane''s newest Friday night market returns to Reddacliff Place on George Street on Friday 27 November, from 4pm to 9pm, the same night as the Lord Mayor''s Lighting of the Christmas Tree.

More than 70 curated food, artisan and boutique traders bring street food, local makers and independent producers together, alongside a pop-up bar showcasing local brewers and distillers. Live music plays through the evening, with themed lighting and immersive installations.

Entry is free, no bookings are needed, and it suits all ages. It''s a good chance to find handmade Christmas gifts before walking up to King George Square for the tree lighting.', story='[{"type": "text", "text": "On Black Friday, Reddacliff Place at the top of the Queen Street Mall turns into an after-work market. Brisbane''s City After Dark Markets return from 4pm to 9pm, timed with the lighting of the city''s Christmas tree a short walk away."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. City After Dark Markets photos coming soon"}, {"type": "text", "text": "More than 70 traders line the square: street food, independent makers and artisan producers, chosen to make it a place to eat, drink and shop. A pop-up bar pours local beer and spirits from Queensland brewers and distillers, and live music runs all evening under themed lighting and installations.", "heading": "70 traders and a pop-up bar"}, {"type": "text", "text": "Come straight from work, find a few handmade gifts, grab dinner from the food stalls, then wander up to King George Square for the Lord Mayor''s Lighting of the Christmas Tree at 6.30pm.", "heading": "Pair it with the tree lighting"}]'::jsonb, highlights='[{"title": "70+ traders", "detail": "Food, makers and boutique stalls"}, {"title": "Free entry", "detail": "No bookings needed"}, {"title": "Pop-up bar", "detail": "Local brewers and distillers"}]'::jsonb, good_to_know='["Free entry, no bookings needed", "Friday 27 November, 4pm to 9pm", "Suitable for all ages", "Bring a bag for your shopping", "Pair it with the tree lighting in King George Square at 6.30pm"]'::jsonb, address='Reddacliff Place, 266 George Street, Brisbane City', venue_about='Reddacliff Place is the open square at the top of the Queen Street Mall, beside the Treasury precinct.', maps_url='https://www.google.com/maps/search/?api=1&query=Reddacliff%20Place%2C%20266%20George%20Street%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='city-after-dark-markets-christmas';
update events set lead='Brisbane City Hall becomes a giant storybook each night in December, with free projection shows every 15 minutes, including a new tale about a grumpy cat called Meowy Christmas.', about='From 4 to 24 December, Brisbane City Hall is transformed each night with colourful projections, music and storytelling. Shows run every 15 minutes from 7.30pm to midnight, so there''s no need to arrive at a set time.

This year''s program includes Meowy Christmas, a new story by local children''s author Melissa Elk about a grumpy cat who finds the Christmas spirit.

It''s free, and best watched from King George Square, beside the city''s 22-metre Christmas tree.', story='[{"type": "text", "text": "After dark in December, the sandstone facade of Brisbane City Hall becomes a screen. Colour, music and story wash across the building in short projection shows, running every 15 minutes from 7.30pm until midnight, every night from 4 to 24 December."}, {"type": "image", "url": "/images/library/unsplash-cmophoto-carousel.jpg", "alt": "Lit carousel at night decorated for Christmas", "layout": "right", "caption": "Stand-in photo: cmophoto.net. City Hall Lights photos coming soon"}, {"type": "text", "text": "This year''s show includes Meowy Christmas, a new story written by local children''s author Melissa Elk. It follows a grumpy cat who, despite himself, finds the Christmas spirit: a gentle, funny tale that suits young children.", "heading": "Meowy Christmas"}, {"type": "text", "text": "Watch from King George Square, where the 22-metre city Christmas tree stands. Because shows repeat every 15 minutes, it''s easy to fit in after dinner in the city, late-night shopping in the Queen Street Mall, or the BrisStyle Twilight Markets on 4 and 18 December.", "heading": "When and where to watch"}]'::jsonb, highlights='[{"title": "Every 15 min", "detail": "7.30pm to midnight"}, {"title": "Free", "detail": "Just turn up"}, {"title": "New story", "detail": "Meowy Christmas by Melissa Elk"}]'::jsonb, good_to_know='["Free, no tickets needed", "Nightly from 4 to 24 December", "Shows every 15 minutes from 7.30pm to midnight", "Watch from King George Square", "Pair it with the BrisStyle Twilight Markets on 4 and 18 December"]'::jsonb, address='Brisbane City Hall, King George Square, Brisbane City', venue_about='Brisbane City Hall, opened in 1930, faces King George Square in the heart of the city.', maps_url='https://www.google.com/maps/search/?api=1&query=Brisbane%20City%20Hall%2C%2064%20Adelaide%20Street%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='city-hall-lights';
update events set lead='Brisbane''s biggest carols night at the Riverstage, with Samantha Jade, Dami Im, Hugh Sheridan, Katie Noonan and Emma Memma. Sold out, but free to watch on the big screen at Roma Street Parkland.', about='The Lord Mayor''s Christmas Carols return to the Riverstage on Saturday 5 December 2026. Gates open at 4pm, pre-show entertainment starts at 5.30pm, and the main show runs from 7pm to 9pm.

The line-up includes Samantha Jade, Dami Im, Hugh Sheridan, Monica Trapaga, Katie Noonan, Dylan Wright, Max Jackson and Jude York, with family favourites Emma Memma and Elvin Melvin. Expect Christmas classics, contemporary favourites and plenty of singalongs.

Riverstage tickets ($8.50 for 13 and over, $5 for ages 6 to 12, free for under 6s) have sold out, with resale available through Ticketmaster. You can also watch the carols free on the big screen at Roma Street Parkland.', story='[{"type": "text", "text": "On the first Saturday in December, the Riverstage at Gardens Point fills with candles and voices for the Lord Mayor''s Christmas Carols, Brisbane''s biggest carols night of the year. Gates open at 4pm, there''s pre-show entertainment from 5.30pm, and the main show runs from 7pm to 9pm."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. Lord Mayor''s Christmas Carols photos coming soon"}, {"type": "text", "text": "This year''s line-up brings together Samantha Jade, Dami Im, Hugh Sheridan, Monica Trapaga, Katie Noonan, Dylan Wright, Max Jackson and Jude York. For the youngest carollers, Emma Memma and Elvin Melvin join in. The program mixes Christmas classics with contemporary favourites and festive surprises.", "heading": "The line-up"}, {"type": "text", "text": "Riverstage tickets have sold out, though resale tickets may come up on Ticketmaster. If you miss out, the whole show is livestreamed free on the big screen at Roma Street Parkland, where you can spread out a picnic rug and sing along.", "heading": "Missed out on tickets?"}]'::jsonb, highlights='[{"title": "10+ performers", "detail": "Samantha Jade, Dami Im and more"}, {"title": "Free big screen", "detail": "Roma Street Parkland"}, {"title": "7pm–9pm", "detail": "Gates 4pm, pre-show 5.30pm"}]'::jsonb, good_to_know='["Riverstage tickets are sold out; check Ticketmaster resale", "Free livestream on the big screen at Roma Street Parkland", "Gates 4pm, pre-show 5.30pm, main show 7pm to 9pm", "Suitable for all ages", "Bring a picnic rug and water", "Information: Brisbane City Council, 07 3403 8888"]'::jsonb, venue_about='The Riverstage is Brisbane''s outdoor concert venue on the river at Gardens Point, beside the City Botanic Gardens.', maps_url='https://www.google.com/maps/search/?api=1&query=Riverstage%2C%2059%20Gardens%20Point%20Road%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='lord-mayors-christmas-carols';
update events set lead='A free treasure hunt for 16 tiny Christmas doors hidden around Brisbane City, made by local artist Mace Robertson, with five new doors this year.', about='From 1 to 25 December, 16 Christmas Tiny Doors are hidden around Brisbane City, each designed and made by local artist Mace Robertson. Five are brand new this year, joining returning favourites.

Pick up a free Christmas Tiny Doors Adventure Map from the Visitor Information Centre in the Queen Street Mall from 1 December, or open the map on your phone from the Visit Brisbane website, then set off to find them all.

It''s free, it runs any time, and it''s a lovely way to keep children busy on a Christmas trip into the city. Found all 16? Share your photos and tag @brisbanecity.', story='[{"type": "text", "text": "Look closely at Brisbane''s walls, steps and corners this December and you might find a door no bigger than your hand. Sixteen Christmas Tiny Doors are hidden around the city, each one a miniature festive scene designed and made by local artist Mace Robertson."}, {"type": "image", "url": "/images/library/unsplash-marnie-rochester-gingerbread.jpg", "alt": "Gingerbread biscuits cut out on a baking tray", "layout": "right", "caption": "Stand-in photo: Marnie Rochester. Christmas Tiny Doors photos coming soon"}, {"type": "text", "text": "Five of the doors are brand new this year, joining favourites from past seasons. Collect a free Christmas Tiny Doors Adventure Map from the Visitor Information Centre in the Queen Street Mall from 1 December, or open the map on your phone, and follow the trail at your own pace.", "heading": "Five new doors this year"}, {"type": "text", "text": "The trail is free and open any time, so it fits around Christmas shopping, lunch in the city, or an evening visit to the City Hall Lights. Allow time to find all 16: children love keeping count, and the hunt takes in parts of the city you might usually walk straight past.", "heading": "Make a day of it"}]'::jsonb, highlights='[{"title": "16 doors", "detail": "5 new this year"}, {"title": "Free", "detail": "Any time, 1 to 25 December"}, {"title": "Local artist", "detail": "Made by Mace Robertson"}]'::jsonb, good_to_know='["Free, any time from 1 to 25 December", "Paper map from the Queen Street Mall Visitor Information Centre", "Map also available online for your phone", "Great for children, so allow time to find all 16", "Share your finds by tagging @brisbanecity"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Brisbane%20Visitor%20Information%20Centre%2C%20Queen%20Street%20Mall%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='christmas-tiny-doors';
update events set lead='Local makers fill King George Square on two December Friday nights, with handmade jewellery, ceramics, art and homewares, food trucks and live music.', about='BrisStyle''s Twilight Markets bring local makers and artisans to King George Square from 4pm to 9pm on Friday 4 and Friday 18 December.

Stalls sell handcrafted jewellery, ceramics, art, homewares and other gift ideas made by local hands, with food trucks and live music through the evening. Entry is free.

The 4 December market falls on the first night of the City Hall Lights, so you can shop, eat and then watch the projections on City Hall next door.', story='[{"type": "text", "text": "Two Friday evenings in December are set aside for local makers. BrisStyle''s Twilight Markets set up in King George Square from 4pm to 9pm on Friday 4 and Friday 18 December, beneath the city''s Christmas tree."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. BrisStyle Twilight Markets photos coming soon"}, {"type": "text", "text": "This is the place for gifts with a story: handcrafted jewellery, ceramics, art and homewares made by local makers and artisans. Food trucks keep everyone fed and live music plays as the square fills up after work.", "heading": "Handmade gifts"}, {"type": "text", "text": "On 4 December, the first night of the season''s City Hall Lights, stay on after the stalls for the projection shows on City Hall, which run every 15 minutes from 7.30pm.", "heading": "Stay for the lights"}]'::jsonb, highlights='[{"title": "2 nights only", "detail": "Friday 4 and 18 December"}, {"title": "Free entry", "detail": "4pm to 9pm"}, {"title": "Local makers", "detail": "Handmade gifts and homewares"}]'::jsonb, good_to_know='["Free entry", "Friday 4 and Friday 18 December only, 4pm to 9pm", "Food trucks and live music", "City Hall Lights start on 4 December, every 15 minutes from 7.30pm"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=King%20George%20Square%2C%20100%20Adelaide%20Street%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='brisstyle-twilight-markets-december';
update events set lead='Children make their own Christmas decoration from natural seed pods on the verandah of Brisbane''s oldest surviving residence, with a short kid-friendly tour while it dries.', about='On Monday 14 and Tuesday 15 December, children can make a Christmas decoration on the grand verandah of Newstead House, Brisbane''s oldest surviving residence. Sessions run from 9.30am to 11am and 12pm to 1.30pm, and cost $15 per child.

Kids decorate natural Crow''s Ash seed pods with coloured paint, sparkly sequins and pipe cleaners. While their creations dry, a volunteer guide leads a short, kid-friendly tour of the House. Then it''s back to the verandah to finish their decoration and take it home for the tree.

Group Set Coffee and M Pressed toasties are available on site, and the gift shop sells ice-cream and light snacks. Food and drink can''t be taken inside the House. Bookings are made through Newstead House.', story='[{"type": "text", "text": "On the wide verandah of Brisbane''s oldest surviving house, children settle in with paint pots and sequins for a Christmas morning or afternoon of making. Newstead House runs its Christmas Kids Craft on Monday 14 and Tuesday 15 December, with two sessions each day."}, {"type": "image", "url": "/images/library/unsplash-marnie-rochester-gingerbread.jpg", "alt": "Gingerbread biscuits cut out on a baking tray", "layout": "right", "caption": "Stand-in photo: Marnie Rochester. Christmas Kids Craft at Newstead House photos coming soon"}, {"type": "text", "text": "Each child decorates natural Crow''s Ash seed pods with coloured paint, sparkly sequins and pipe cleaners. While the decorations dry, a volunteer guide takes the children on an express tour of the House, sharing the stories behind it in a way that keeps little ones interested. Then they return to assemble their decoration, ready to hang on the tree at home.", "heading": "Seed pods, sequins and a story"}, {"type": "text", "text": "Group Set Coffee and M Pressed toasties are on site for parents, and the Newstead House Gift Shop sells ice-cream and light snacks. Food and drink can''t be taken inside the House. There''s a public toilet, and disabled access is available, so contact Newstead House for details.", "heading": "For the grown-ups"}]'::jsonb, highlights='[{"title": "$15 per child", "detail": "Decoration to take home"}, {"title": "4 sessions", "detail": "14 and 15 December"}, {"title": "Heritage tour", "detail": "Brisbane''s oldest surviving home"}]'::jsonb, good_to_know='["Book online through Newstead House", "Sessions 9.30am to 11am and 12pm to 1.30pm", "$15 per child", "Coffee, toasties, ice-cream and snacks on site", "No food or drink inside the House", "Disabled access available: contact Newstead House"]'::jsonb, venue_about='Newstead House is Brisbane''s oldest surviving residence, set in Newstead Park overlooking the Brisbane River.', maps_url='https://www.google.com/maps/search/?api=1&query=Newstead%20House%2C%20Newstead%20Park%2C%20Breakfast%20Creek%20Road%2C%20Newstead%20QLD%204006', updated_at=now() where slug='christmas-kids-craft-newstead-house';
update events set lead='Roving Christmas performers and pop-up entertainment in the Queen Street Mall through December, from lunchtime into late-night shopping.', about='Throughout December, Brisbane City Council brings pop-up entertainment and roving Christmas performances to the Queen Street Mall, from lunchtime and into late-night shopping.

It''s free, and an easy way to add some Christmas atmosphere to a shopping trip into the city. Check the Council''s Christmas in Brisbane page for the latest program.

The Mall is also where you''ll find the Visitor Information Centre, starting point for the Christmas Tiny Doors trail, and it''s a short walk to King George Square for the city tree and the City Hall Lights.', story='[{"type": "text", "text": "Christmas shopping in the city comes with a soundtrack in December. Pop-up entertainment and roving performers appear along the Queen Street Mall from lunchtime and into late-night shopping, adding a little festive cheer as you hunt for gifts."}, {"type": "image", "url": "/images/library/unsplash-cmophoto-carousel.jpg", "alt": "Lit carousel at night decorated for Christmas", "layout": "right", "caption": "Stand-in photo: cmophoto.net. Queen Street Mall Christmas photos coming soon"}, {"type": "text", "text": "Start at the Visitor Information Centre in the Mall to pick up a free Christmas Tiny Doors Adventure Map, then follow the trail of 16 tiny doors around the city. In the evening, walk up to King George Square to see the 22-metre Christmas tree and the City Hall Lights projections, which run every 15 minutes from 7.30pm.", "heading": "Make a day of it in the city"}]'::jsonb, highlights='[{"title": "Free", "detail": "All through December"}, {"title": "Lunch to late", "detail": "Into late-night shopping"}, {"title": "In the city", "detail": "Near the tree and City Hall Lights"}]'::jsonb, good_to_know='["Free", "Check the Council''s Christmas in Brisbane page for the daily program", "Combine it with Christmas shopping in the city", "Pick up a Tiny Doors map at the Visitor Information Centre in the Mall"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Queen%20Street%20Mall%2C%20Brisbane%20City%20QLD', updated_at=now() where slug='queen-street-mall-christmas';
update events set lead='A Christmas twilight edition of Milton Markets, with stalls, food and photos with Santa.', story='[{"type": "text", "text": "Milton Markets goes after dark for a Christmas twilight market, from 4pm to 10pm. Wander the stalls for gifts, grab dinner from the food vendors and line up for photos with Santa."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. Milton Markets Christmas Twilight photos coming soon"}, {"type": "text", "text": "Entry is free. Check the market''s own pages for the latest stallholder and Santa details before you go.", "heading": "Before you go"}]'::jsonb, highlights='[{"title": "Free entry", "detail": "4pm to 10pm"}, {"title": "Santa photos", "detail": "Snaps with Santa"}, {"title": "Twilight market", "detail": "Stalls and food"}]'::jsonb, updated_at=now() where slug='milton-markets-christmas-twilight';
